def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Build lists for easy indexing
    me = [h[0] for h in history]
    op = [h[1] for h in history]

    # Early game: cooperate to establish trust
    if n < 4:
        return 'C'

    opp_c = op.count('C')
    opp_d = n - opp_c
    coop_rate = opp_c / n

    # Never-defected opponent: cooperate, but probe occasionally late
    if opp_d == 0:
        if n >= 95 and rng.random() < 0.3:
            return 'D'
        return 'C'

    # Always-defected opponent: defect almost always
    if opp_c == 0:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Count recent behavior
    recent = op[-10:] if n >= 10 else op
    recent_c = recent.count('C')
    recent_d = len(recent) - recent_c

    # Consecutive opponent defections at end
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            consec_d += 1
        else:
            break

    # Consecutive opponent cooperations at end
    consec_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            consec_c += 1
        else:
            break

    # Detect strong reciprocity: opponent copies our previous move
    if n >= 5:
        matches = 0
        total = 0
        for i in range(1, n):
            if op[i] == me[i - 1]:
                matches += 1
            total += 1
        mirror = matches / total if total else 0
    else:
        mirror = 0.0

    remaining = 100 - n

    # Late game: if opponent is highly cooperative, cooperate until the very end,
    # then defect on the last one or two rounds for extra points.
    if remaining <= 2 and coop_rate > 0.5 and consec_d == 0:
        return 'D'

    # If opponent is very cooperative and not currently defecting, cooperate,
    # but occasionally probe to detect exploitability.
    if coop_rate >= 0.85 and consec_d == 0:
        if remaining > 10 and n % 19 == 0 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # If opponent is heavily defecting, defect to defend.
    if coop_rate <= 0.35 or recent_d >= 6:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Opponent regularly retaliates (mirrors): cooperate to keep mutual C.
    if mirror > 0.65 and consec_d == 0:
        return 'C'

    # If opponent is in a defection streak, punish, but forgive after a few.
    if consec_d == 1:
        # Single defection: retaliate once but not permanently
        if mirror > 0.5:
            return 'D'
        return 'D'
    if consec_d == 2:
        # Two in a row: defect, but consider forgiving if overall cooperative
        if coop_rate > 0.6 and rng.random() < 0.4:
            return 'C'
        return 'D'
    if consec_d >= 3:
        # Sustained defection: mostly defect, try occasional reset
        if consec_d >= 6 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last. Respond with cooperation but be alert.
    if coop_rate >= 0.5:
        # Mostly cooperative: cooperate, occasional probing
        if remaining > 10 and rng.random() < 0.04:
            return 'D'
        return 'C'
    else:
        # Mixed opponent currently cooperating: cooperate but test occasionally
        if rng.random() < 0.25:
            return 'D'
        return 'C'
